//TrialChambersStructurePools structure pool data, maps to vanilla net.minecraft.data.worldgen.TrialChambersStructurePools
public static class TrialChambersStructurePools
{
    public static readonly ResourceKey<RegistryPool> START = Pools.CreateKey("trial_chambers/chamber/end");
    public static readonly ResourceKey<RegistryPool> HALLWAY_FALLBACK = Pools.CreateKey("trial_chambers/hallway/fallback");

    //ALIAS_BINDINGS the spawner alias groups, maps to vanilla ALIAS_BINDINGS
    //The first group swaps all ranged spawners together, the other two pick a melee/small melee spawner at random
    public static readonly IReadOnlyList<GameAlias> ALIAS_BINDINGS = new List<GameAlias>
    {
        new RandomGroupPoolAlias(WeightedList<List<GameAlias>>.Builder()
            .Add(new List<GameAlias>
            {
                new DirectPoolAlias(Identifier.Parse(Spawner("contents/ranged")),
                    Identifier.Parse(Spawner("ranged/skeleton"))),
                new DirectPoolAlias(Identifier.Parse(Spawner("contents/slow_ranged")),
                    Identifier.Parse(Spawner("slow_ranged/skeleton"))),
            })
            .Add(new List<GameAlias>
            {
                new DirectPoolAlias(Identifier.Parse(Spawner("contents/ranged")),
                    Identifier.Parse(Spawner("ranged/stray"))),
                new DirectPoolAlias(Identifier.Parse(Spawner("contents/slow_ranged")),
                    Identifier.Parse(Spawner("slow_ranged/stray"))),
            })
            .Add(new List<GameAlias>
            {
                new DirectPoolAlias(Identifier.Parse(Spawner("contents/ranged")),
                    Identifier.Parse(Spawner("ranged/poison_skeleton"))),
                new DirectPoolAlias(Identifier.Parse(Spawner("contents/slow_ranged")),
                    Identifier.Parse(Spawner("slow_ranged/poison_skeleton"))),
            })
            .Build()),
        new RandomPoolAlias(Identifier.Parse(Spawner("contents/melee")),
            WeightedList<Identifier>.Builder()
                .Add(Identifier.Parse(Spawner("melee/zombie")))
                .Add(Identifier.Parse(Spawner("melee/husk")))
                .Add(Identifier.Parse(Spawner("melee/spider")))
                .Build()),
        new RandomPoolAlias(Identifier.Parse(Spawner("contents/small_melee")),
            WeightedList<Identifier>.Builder()
                .Add(Identifier.Parse(Spawner("small_melee/slime")))
                .Add(Identifier.Parse(Spawner("small_melee/cave_spider")))
                .Add(Identifier.Parse(Spawner("small_melee/silverfish")))
                .Add(Identifier.Parse(Spawner("small_melee/baby_zombie")))
                .Build()),
    };

    //Spawner builds the spawner pool path, maps to vanilla spawner(String)
    public static string Spawner(string alias) => "trial_chambers/spawner/" + alias;

